const int stepPin = 2; 
const int dirPin  = 5; 
const int enPin   = 8;

const int stepsPer60Deg = 33; // 33 шага = ~60 градусов

void setup() {
  pinMode(stepPin, OUTPUT);
  pinMode(dirPin, OUTPUT);
  pinMode(enPin, OUTPUT);

  digitalWrite(enPin, LOW);   // Включаем драйвер
  digitalWrite(dirPin, HIGH); // Направление вращения
}

void loop() {
  // Поворот на 60 градусов
  for(int x = 0; x < stepsPer60Deg; x++) {
    digitalWrite(stepPin, HIGH);
    delayMicroseconds(2000);
    digitalWrite(stepPin, LOW);
    delayMicroseconds(2000);
  }

  // Пауза 30 секунд
  delay(30000); 
}
